+ * PowerPoint のファイルのマスターは tx1 を dk1 に、bg1 を lt1 に対応させる (要素 p:clrMap) ので、同じ色になる
+ */
+export function schemeColor(name: ThemeColorName): string {
+  switch (name) {
+    case "dk1":
+      return "tx1";
+    case "lt1":
+      return "bg1";
+    case "dk2":
+      return "tx2";
+    case "lt2":
